package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** The six existing decimal stories use their visible quantities, units and counts. */
public final class PublicDecimalContexts {
 private PublicDecimalContexts(){}
 public static boolean supports(String id){return DecimalMeasureStories.supports(id)||DecimalMeasureGroups.supports(id)||DecimalTwoStepStories.supports(id);}
 private static final String NUMBER="([0-9]{1,9}(?:\\.[0-9]{1,3})?)",COUNT="([0-9]{1,9})";
 public record Givens(String id,String firstRaw,String secondRaw,String countRaw,String unit,Rational first,Rational second,BigInteger count,Rational intermediate,Rational result){
  public Rational value(){return result;}
  public boolean finitePossible(){BigInteger d=result.d;for(int prime:List.of(2,5)){BigInteger p=BigInteger.valueOf(prime);while(d.mod(p).signum()==0)d=d.divide(p);}return d.equals(BigInteger.ONE);}
  public String expression(){String x="("+firstRaw+")",y=secondRaw==null?"":"("+secondRaw+")",k=countRaw==null?"":"("+countRaw+")";return switch(id){case DecimalMeasureStories.ADD->x+" + "+y;case DecimalMeasureStories.SUB->x+" - "+y;case DecimalMeasureGroups.MUL->x+" * "+k;case DecimalMeasureGroups.DIV->x+" / "+k;case DecimalTwoStepStories.REMAIN->"("+x+" * "+k+") - "+y;default->"("+x+" + "+y+") / "+k;};}
 }
 private static String template(String id,String u){
  if(DecimalTwoStepStories.supports(id))return DecimalTwoStepStories.prompt(id,"__X__","__Y__",1,u).replace("1","__K__");
  if(DecimalMeasureStories.supports(id)){boolean add=DecimalMeasureStories.ADD.equals(id);return u.equals("m")?(add?"끈 __X__ m와 __Y__ m를 겹치지 않게 잇습니다.\n이어진 끈의 길이는 몇 m인가요?":"끈 __X__ m에서 __Y__ m를 잘라 냈습니다.\n남은 끈의 길이는 몇 m인가요?"):u.equals("L")?(add?"물 __X__ L에 물 __Y__ L를 더 부었습니다.\n모두 몇 L인가요?":"물 __X__ L에서 __Y__ L를 사용했습니다.\n남은 물은 몇 L인가요?"):(add?"쌀 __X__ kg에 쌀 __Y__ kg을 더 담았습니다.\n모두 몇 kg인가요?":"쌀 __X__ kg에서 __Y__ kg을 사용했습니다.\n남은 쌀은 몇 kg인가요?");}
  boolean mul=DecimalMeasureGroups.MUL.equals(id);return mul?(u.equals("m")?"__X__ m인 끈 __K__개를 겹치지 않게 잇습니다.\n이어진 끈의 길이는 몇 m인가요?":u.equals("L")?"물 __X__ L가 든 병 __K__개가 있습니다.\n물은 모두 몇 L인가요?":"쌀 __X__ kg이 든 봉지 __K__개가 있습니다.\n쌀은 모두 몇 kg인가요?"):(u.equals("m")?"끈 __X__ m를 길이가 같은 __K__조각으로 나눕니다.\n한 조각은 몇 m인가요?":u.equals("L")?"물 __X__ L를 __K__병에 똑같이 나눕니다.\n한 병에는 몇 L가 들어가나요?":"쌀 __X__ kg을 __K__봉지에 똑같이 나눕니다.\n한 봉지에는 몇 kg이 들어가나요?");
 }
 private static Rational rational(String raw){BigDecimal x=new BigDecimal(raw);return new Rational(x.unscaledValue(),BigInteger.TEN.pow(x.scale()));}
 public static Givens readGeneral(Question q){
  if(q==null||!supports(q.skillId)||q.prompt==null||q.prompt.length()>600)return null;
  for(String unit:List.of("m","L","kg")){String pattern=Pattern.quote(template(q.skillId,unit)).replace("__X__","\\E"+NUMBER+"\\Q").replace("__Y__","\\E"+NUMBER+"\\Q").replace("__K__","\\E"+COUNT+"\\Q");Matcher m=Pattern.compile(pattern).matcher(q.prompt);if(!m.matches())continue;
   boolean two=DecimalTwoStepStories.supports(q.skillId),remain=DecimalTwoStepStories.REMAIN.equals(q.skillId),pair=DecimalMeasureStories.supports(q.skillId);String x=m.group(1),y=pair?m.group(2):two?m.group(remain?3:2):null,k=pair?null:m.group(two&&!remain?3:2);BigInteger count=k==null?null:new BigInteger(k);if(count!=null&&count.signum()<=0)return null;Rational first=rational(x),second=y==null?null:rational(y),n=count==null?null:new Rational(count,BigInteger.ONE),intermediate=null,result;
   switch(q.skillId){case DecimalMeasureStories.ADD:result=first.add(second);break;case DecimalMeasureStories.SUB:result=first.sub(second);break;case DecimalMeasureGroups.MUL:result=first.mul(n);break;case DecimalMeasureGroups.DIV:result=first.div(n);break;case DecimalTwoStepStories.REMAIN:intermediate=first.mul(n);result=intermediate.sub(second);break;default:intermediate=first.add(second);result=intermediate.div(n);}
   if(result.compareTo(Rational.ZERO)<0)return null;return new Givens(q.skillId,x,y,k,unit,first,second,count,intermediate,result);
  }return null;
 }
 public static DecimalMeasureStories.Givens measureGivens(Question q){Givens g=readGeneral(q);return g==null||!DecimalMeasureStories.supports(g.id)?null:new DecimalMeasureStories.Givens(g.firstRaw,g.secondRaw,g.unit,DecimalMeasureStories.ADD.equals(g.id));}
 public static DecimalMeasureGroups.Givens groupGivens(Question q){Givens g=readGeneral(q);return g==null||!DecimalMeasureGroups.supports(g.id)?null:new DecimalMeasureGroups.Givens(g.firstRaw,g.count.intValueExact(),g.unit,DecimalMeasureGroups.MUL.equals(g.id));}
 public static DecimalTwoStepStories.Givens twoStepGivens(Question q){Givens g=readGeneral(q);return g==null||!DecimalTwoStepStories.supports(g.id)?null:new DecimalTwoStepStories.Givens(g.firstRaw,g.secondRaw,g.count.intValueExact(),g.unit,DecimalTwoStepStories.REMAIN.equals(g.id));}
 public static Rational value(Question q){Givens g=readGeneral(q);return g==null?null:g.value();}
 public static Question workQuestion(Question q){Givens g=readGeneral(q);if(g==null)return null;Question visible=new Question(q.skillId,q.prompt,g.expression(),g.value().toString());visible.kind="number";visible.stepSupport=q.stepSupport;visible.calculationMethod=q.calculationMethod;visible.answerFormat=q.answerFormat;visible.decimal=q.decimal;return visible;}
 public static Rational numericInput(String value){return DecimalWholeQuotients.numericInput(value);}
 public static boolean acceptsStep(String value,String expected,String format){return DecimalWholeQuotients.acceptsStep(value,expected,format);}
 public static StudyGuide guide(Question q){
  Givens g=readGeneral(q);if(g==null)return null;
  if(DecimalMeasureStories.supports(g.id)){boolean add=DecimalMeasureStories.ADD.equals(g.id);Question calc=new Question(add?"decimalAdd":"decimalSub",g.firstRaw+(add?" + ":" - ")+g.secondRaw,"","");DecimalArithmeticRelations.attach(calc);StudyGuide arithmetic=calc.studyGuide;
   arithmetic.frames.get(0).instruction="문제의 첫 번째 양을 쓰세요.";arithmetic.frames.get(0).before="첫째 양 x = ";arithmetic.frames.get(1).instruction="문제의 두 번째 양을 쓰세요.";arithmetic.frames.get(1).before="둘째 양 y = ";arithmetic.frames.get(3).instruction="소수점 이동이 한 자리면 10배, 두 자리면 100배, 세 자리면 1000배입니다. 0자리면 1입니다.";
   StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-measure-story-v1";Map<String,String> choices=new LinkedHashMap<>();choices.put("add","전체 양 = 첫째 양 + 둘째 양");choices.put("sub","남은 양 = 처음 양 − 사용한 양");h.choice("문장에서 구하는 양에 맞는 관계를 고르세요.",choices,add?"add":"sub");h.frames.addAll(arithmetic.frames);return h;
  }
  if(DecimalMeasureGroups.supports(g.id)){boolean mul=DecimalMeasureGroups.MUL.equals(g.id);Question calc=new Question(mul?"decimalMul":"decimalDivInt",g.firstRaw+(mul?" × ":" ÷ ")+g.countRaw,"","");StudyGuide arithmetic=mul?DecimalWholeProducts.guide(calc):DecimalWholeQuotients.guide(calc);StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-measure-groups-v1";Map<String,String> choices=new LinkedHashMap<>();choices.put("mul","전체 양 = 한 묶음의 양 × 묶음 수");choices.put("div","한 묶음의 양 = 전체 양 ÷ 묶음 수");h.choice("문장에서 구하는 양에 맞는 관계를 고르세요.",choices,mul?"mul":"div");h.frames.addAll(arithmetic.frames);h.frames.get(1).instruction="문제의 양을 쓰세요.";h.frames.get(2).instruction="묶음 수를 쓰세요.";if(arithmetic.resultNumeratorFrame!=null)h.fractionResult(arithmetic.resultNumeratorFrame+1,arithmetic.resultDenominatorFrame+1);return h;
  }
  boolean remaining=DecimalTwoStepStories.REMAIN.equals(g.id);BigDecimal x=new BigDecimal(g.firstRaw),y=new BigDecimal(g.secondRaw),first=remaining?x.multiply(new BigDecimal(g.count)):x.add(y);StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-two-step-v1";Map<String,String> choices=new LinkedHashMap<>();choices.put("mulSub","한 묶음의 양 × 묶음 수, 그다음 사용한 양 빼기");choices.put("addDiv","두 양 더하기, 그다음 묶음 수로 나누기");h.choice("문장에 맞는 계산 순서를 고르세요.",choices,remaining?"mulSub":"addDiv");step(h,"첫째 양을 쓰세요.","첫째 양 x = ",g.firstRaw,true);step(h,"둘째 양을 쓰세요.","둘째 양 y = ",g.secondRaw,true);step(h,"묶음 수를 쓰세요.","묶음 수 k = ",g.count.toString(),false);step(h,remaining?"한 묶음의 양에 묶음 수를 곱하세요.":"두 양을 더하세요.",remaining?"중간 양 P = x × k = ":"중간 양 P = x + y = ",first.toPlainString(),true);
  if(g.finitePossible()){BigDecimal result=remaining?first.subtract(y):first.divide(new BigDecimal(g.count));step(h,remaining?"중간 양에서 사용한 양을 빼세요.":"중간 양을 묶음 수로 나누세요.",remaining?"남은 양 R = P − y = ":"한 묶음의 양 R = P ÷ k = ",result.stripTrailingZeros().toPlainString(),true);return h;}
  int p=first.scale();BigInteger u=BigInteger.TEN.pow(p),a=first.movePointRight(p).toBigIntegerExact(),d=u.multiply(g.count),common=a.gcd(d);step(h,"두 원래 양의 소수 자릿수 중 더 긴 자릿수를 쓰세요.","소수 자릿수 p = ",Integer.toString(p),false);step(h,"소수 자릿수에 맞는 배수를 쓰세요.","자릿값 배수 u = ",u.toString(),false);step(h,"중간 양의 소수점을 오른쪽으로 p칸 옮기세요.","분자 A = P × u = ",a.toString(),false);step(h,"배수에 묶음 수를 곱해 분모를 구하세요.","분모 D = u × k = ",d.toString(),false);step(h,"분자와 분모의 최대공약수를 구하세요.","최대공약수 g = gcd(A, D) = ",common.toString(),false);step(h,"분자를 최대공약수로 나누세요.","분자 n = A ÷ g = ",a.divide(common).toString(),false);step(h,"분모를 같은 최대공약수로 나누세요.","분모 b = D ÷ g = ",d.divide(common).toString(),false);return h.fractionResult(10,11);
 }
 private static void step(StudyGuide h,String instruction,String before,String expected,boolean decimal){h.step(instruction,before,"",expected);if(decimal)h.frames.get(h.frames.size()-1).inputFormat="decimalValue";}
 public static Map<String,String> references(Question q,int stage,List<String> entries){Givens g=readGeneral(q);StudyGuide h=guide(q);if(g==null||h==null||entries==null||stage<0||stage>=h.frames.size())return Map.of();List<Integer> needed=List.of();
  if(DecimalMeasureStories.supports(g.id)){if(stage==3)needed=List.of(1,2);else if(stage==4)needed=List.of(3);else if(stage==5)needed=List.of(1,3,4);else if(stage==6)needed=List.of(2,3,4);else if(stage==7)needed=List.of(5,6);else if(stage==8)needed=List.of(3,4,7);}
  else if(DecimalMeasureGroups.MUL.equals(g.id)){if(stage==3)needed=List.of(1);else if(stage==4)needed=List.of(1,3);else if(stage==5)needed=List.of(4,2);else if(stage==6)needed=List.of(5,3);}
  else if(DecimalMeasureGroups.DIV.equals(g.id)){if(stage==3)needed=List.of(1);else if(stage==4)needed=List.of(3);else if(stage==5)needed=g.finitePossible()?List.of(1,3,4):List.of(1,4);else if(stage==6)needed=g.finitePossible()?List.of(5,2):List.of(4,2);else if(stage==7)needed=g.finitePossible()?List.of(6,4):List.of(5,6);else if(stage==8)needed=List.of(5,7);else if(stage==9)needed=List.of(6,7);}
  else{if(stage==4)needed=DecimalTwoStepStories.REMAIN.equals(g.id)?List.of(1,3):List.of(1,2);else if(stage==5)needed=g.finitePossible()?(DecimalTwoStepStories.REMAIN.equals(g.id)?List.of(4,2):List.of(4,3)):List.of(1,2);else if(stage==6)needed=List.of(5);else if(stage==7)needed=List.of(4,5,6);else if(stage==8)needed=List.of(6,3);else if(stage==9)needed=List.of(7,8);else if(stage==10)needed=List.of(7,9);else if(stage==11)needed=List.of(8,9);}
  Map<String,String> out=new LinkedHashMap<>();for(int index:needed)if(index<stage&&index<entries.size()){StudyGuide.Frame f=h.frames.get(index);if(f.options.isEmpty()&&acceptsStep(entries.get(index),f.expected,f.inputFormat))out.put(f.before,entries.get(index));}return out;
 }
 public static int errorPart(Question q,String input){Givens g=readGeneral(q);if(g==null||input==null||input.length()>120||FractionInput.invalidPart(input)!=0)return 0;String[] parts=FractionInput.parts(input);if(parts==null)return 0;BigInteger n=new BigInteger(parts[0]),d=new BigInteger(parts[1]);if(n.multiply(g.result.d).equals(g.result.n.multiply(d)))return 0;if(d.equals(g.result.d))return 1;if(n.equals(g.result.n))return 2;return 0;}
 static Checker.Result check(Question q,List<String> answers){Givens g=readGeneral(q);if(g==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");String original=answers.get(0);if(original.length()>240)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 확인 필요");String raw=Expression.normalize(original.trim());if(raw.length()>120)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 확인 필요");if("fraction".equals(q.answerFormat)&&!raw.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"분수로 입력 필요");if("decimal".equals(q.answerFormat)&&(!raw.contains(".")||raw.contains("/"))||"decimalValue".equals(q.answerFormat)&&raw.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"소수로 입력 필요");Rational value=numericInput(raw);if(value==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 확인 필요");boolean same=value.equals(g.result);return new Checker.Result(same?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,same?-1:0,same?"계산 확인 완료":"이 답 확인",same?0:errorPart(q,raw));}
}
